  // Format Helper
  function formatRp(val) {
    return 'Rp ' + Math.round(val || 0).toLocaleString('id-ID');
  }

  function formatNum(val) {
    return Math.round(val || 0).toLocaleString('id-ID');
  }

  // Dark / Light Theme
  const root = document.documentElement;
  const themeToggle = document.getElementById('themeToggle');
  const themeIcon = document.getElementById('themeIcon');
  const themeText = document.getElementById('themeText');

  function applyTheme(theme) {
    const isDark = theme === 'dark';
    root.classList.toggle('dark', isDark);
    themeIcon.textContent = isDark ? '☀' : '☾';
    themeText.textContent = isDark ? 'Terang' : 'Gelap';
    setTimeout(redrawAllCharts, 50);
  }

  applyTheme(localStorage.getItem('sales-theme') || 'light');

  themeToggle.addEventListener('click', () => {
    const next = root.classList.contains('dark') ? 'light' : 'dark';
    localStorage.setItem('sales-theme', next);
    applyTheme(next);
  });

  // Table Switching & Search
  let activeTableTab = 'outlets';
  function switchTable(tabName, btnElement) {
    activeTableTab = tabName;
    document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
    if (btnElement) {
      btnElement.classList.add('active');
    } else {
      const targetBtn = document.querySelector(`.tab-btn[onclick*="'${tabName}'"]`);
      if (targetBtn) targetBtn.classList.add('active');
    }

    document.getElementById('table-outlets').style.display = tabName === 'outlets' ? 'block' : 'none';
    document.getElementById('table-areas').style.display = tabName === 'areas' ? 'block' : 'none';
    document.getElementById('table-products').style.display = tabName === 'products' ? 'block' : 'none';

    const productLimitWrapper = document.getElementById('productLimitWrapper');
    const searchInput = document.getElementById('tableSearchInput');
    const summaryEl = document.getElementById('productSearchSummary');

    if (tabName === 'products') {
      if (productLimitWrapper) productLimitWrapper.style.display = 'flex';
      if (searchInput) searchInput.placeholder = '🔍 Cari kata kunci produk (misal: jas, sandal, prima, botol)...';
      renderProductsTable(currentDashboardData.products);
    } else {
      if (productLimitWrapper) productLimitWrapper.style.display = 'none';
      if (summaryEl) summaryEl.style.display = 'none';
      if (searchInput) {
        searchInput.placeholder = tabName === 'outlets' ? '🔍 Cari nama konter / outlet...' : '🔍 Cari nama area...';
      }
      filterTable();
    }
  }

  function filterTable() {
    const query = (document.getElementById('tableSearchInput') ? document.getElementById('tableSearchInput').value : '').toLowerCase().trim();
    if (activeTableTab === 'products') {
      renderProductsTable(currentDashboardData.products);
      return;
    }
    const tableId = activeTableTab === 'outlets' ? 'outletsTable' : 'areasTable';
    const rows = document.querySelectorAll('#' + tableId + ' tbody tr');
    rows.forEach(row => {
      const text = (row.cells[1] ? row.cells[1].innerText : '').toLowerCase();
      row.style.display = text.includes(query) ? '' : 'none';
    });
  }

  function onSearchInput(val) {
    const clearBtn = document.getElementById('clearSearchBtn');
    if (clearBtn) clearBtn.style.display = val.trim() ? 'block' : 'none';

    if (activeTableTab === 'products') {
      renderProductsTable(currentDashboardData.products);
    } else {
      filterTable();
    }
  }

  function clearSearch() {
    const searchInput = document.getElementById('tableSearchInput');
    if (searchInput) {
      searchInput.value = '';
      onSearchInput('');
      searchInput.focus();
    }
  }

  function onProductFilterChange() {
    if (activeTableTab === 'products') {
      renderProductsTable(currentDashboardData.products);
    }
  }

  // Cascading Filter when Area changes
  function onAreaChange() {
    const areaVal = document.getElementById('filterArea').value;
    const outletSelect = document.getElementById('filterOutlet');
    
    // Filter available outlets in the select dropdown
    const availableOutlets = new Set();
    RAW_SALES.forEach(r => {
      if (!areaVal || r[4] === areaVal) {
        availableOutlets.add(r[3]);
      }
    });

    const currentOutletVal = outletSelect.value;
    outletSelect.innerHTML = `<option value="">Semua Outlet (${availableOutlets.size})</option>`;
    Array.from(availableOutlets).sort().forEach(o => {
      const opt = document.createElement('option');
      opt.value = o;
      opt.textContent = o;
      if (o === currentOutletVal && availableOutlets.has(currentOutletVal)) {
        opt.selected = true;
      }
      outletSelect.appendChild(opt);
    });

    applyFilters();
  }

  function formatDisplayDate(dStr) {
    if (!dStr) return '';
    const parts = dStr.split('-');
    if (parts.length < 3) return dStr;
    const d = parseInt(parts[2], 10);
    const m = ["", "Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Agu", "Sep", "Okt", "Nov", "Des"][parseInt(parts[1], 10)] || parts[1];
    return d + ' ' + m + ' ' + parts[0];
  }

