  // State for Calendar Date Picker
  let calCurrentYear = 2026;
  let calCurrentMonth = 0; // 0 = Jan, 1 = Feb, etc.
  let calTempStartDate = '';
  let calTempEndDate = '';

  function openCalendarModal(e) {
    if (e) e.stopPropagation();
    const modal = document.getElementById('calendarModalOverlay');
    if (!modal) return;

    calTempStartDate = document.getElementById('filterStartDate').value || '';
    calTempEndDate = document.getElementById('filterEndDate').value || '';

    if (calTempStartDate) {
      const parts = calTempStartDate.split('-');
      calCurrentYear = parseInt(parts[0], 10) || 2026;
      calCurrentMonth = (parseInt(parts[1], 10) || 1) - 1;
    } else {
      calCurrentYear = 2026;
      calCurrentMonth = 0;
    }

    syncCalSelectors();
    renderCalendarGrid();
    updateCalHeaderPills();
    modal.style.display = 'flex';
  }

  function closeCalendarModal(e) {
    if (e) e.stopPropagation();
    const modal = document.getElementById('calendarModalOverlay');
    if (modal) modal.style.display = 'none';
  }

  function syncCalSelectors() {
    const monthSelect = document.getElementById('calMonthSelect');
    const yearSelect = document.getElementById('calYearSelect');
    if (monthSelect) monthSelect.value = String(calCurrentMonth);
    if (yearSelect) yearSelect.value = String(calCurrentYear);
  }

  function onCalSelectChange() {
    const monthSelect = document.getElementById('calMonthSelect');
    const yearSelect = document.getElementById('calYearSelect');
    if (monthSelect) calCurrentMonth = parseInt(monthSelect.value, 10);
    if (yearSelect) calCurrentYear = parseInt(yearSelect.value, 10);
    renderCalendarGrid();
  }

  function navCalendarMonth(direction) {
    calCurrentMonth += direction;
    if (calCurrentMonth < 0) {
      calCurrentMonth = 11;
      calCurrentYear--;
    } else if (calCurrentMonth > 11) {
      calCurrentMonth = 0;
      calCurrentYear++;
    }
    syncCalSelectors();
    renderCalendarGrid();
  }

  function formatPillDate(dStr) {
    if (!dStr) return 'Pilih Tanggal ▾';
    const parts = dStr.split('-');
    if (parts.length < 3) return dStr;
    const d = String(parseInt(parts[2], 10)).padStart(2, '0');
    const m = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"][parseInt(parts[1], 10) - 1] || parts[1];
    return `${d} ${m}, ${parts[0]}`;
  }

  function updateCalHeaderPills() {
    const fromPill = document.getElementById('calFromDisplay');
    const toPill = document.getElementById('calToDisplay');
    if (fromPill) {
      fromPill.textContent = formatPillDate(calTempStartDate);
      fromPill.classList.toggle('active', Boolean(calTempStartDate));
    }
    if (toPill) {
      toPill.textContent = formatPillDate(calTempEndDate);
      toPill.classList.toggle('active', Boolean(calTempEndDate));
    }
  }

  function onDateCellClick(dStr) {
    if (!calTempStartDate || (calTempStartDate && calTempEndDate)) {
      calTempStartDate = dStr;
      calTempEndDate = '';
    } else if (calTempStartDate && !calTempEndDate) {
      if (dStr < calTempStartDate) {
        calTempEndDate = calTempStartDate;
        calTempStartDate = dStr;
      } else {
        calTempEndDate = dStr;
      }
    }
    updateCalHeaderPills();
    renderCalendarGrid();
  }

  function renderCalendarGrid() {
    const grid = document.getElementById('calDaysGrid');
    if (!grid) return;

    grid.innerHTML = '';

    const firstDayIndex = new Date(calCurrentYear, calCurrentMonth, 1).getDay(); // 0 = Sunday
    const daysInMonth = new Date(calCurrentYear, calCurrentMonth + 1, 0).getDate();
    const daysInPrevMonth = new Date(calCurrentYear, calCurrentMonth, 0).getDate();

    // Previous month trailing days
    for (let i = firstDayIndex - 1; i >= 0; i--) {
      const prevD = daysInPrevMonth - i;
      const cell = document.createElement('div');
      cell.className = 'cal-day-cell other-month';
      cell.textContent = String(prevD).padStart(2, '0');
      grid.appendChild(cell);
    }

    // Current month days
    for (let d = 1; d <= daysInMonth; d++) {
      const mStr = String(calCurrentMonth + 1).padStart(2, '0');
      const dStr = String(d).padStart(2, '0');
      const dateKey = `${calCurrentYear}-${mStr}-${dStr}`;
      const dayOfWeek = new Date(calCurrentYear, calCurrentMonth, d).getDay(); // 0 = Sun, 6 = Sat
      const holidayName = INDONESIA_HOLIDAYS[dateKey];

      const cell = document.createElement('div');
      cell.className = 'cal-day-cell';
      cell.textContent = dStr;
      cell.title = holidayName ? `${dateKey} (${holidayName})` : dateKey;

      if (dayOfWeek === 0) cell.classList.add('sunday');
      if (dayOfWeek === 6) cell.classList.add('saturday');

      if (holidayName) {
        cell.classList.add('holiday');
        const dot = document.createElement('span');
        dot.className = 'holiday-dot';
        cell.appendChild(dot);
      }

      // Check selection state
      if (calTempStartDate && dateKey === calTempStartDate) {
        cell.classList.add('active-endpoint', 'range-start');
      }
      if (calTempEndDate && dateKey === calTempEndDate) {
        cell.classList.add('active-endpoint', 'range-end');
      }
      if (calTempStartDate && calTempEndDate && dateKey > calTempStartDate && dateKey < calTempEndDate) {
        cell.classList.add('in-range');
      }

      cell.onclick = () => onDateCellClick(dateKey);
      grid.appendChild(cell);
    }

    // Next month leading days
    const totalRendered = firstDayIndex + daysInMonth;
    const remaining = (7 - (totalRendered % 7)) % 7;
    for (let i = 1; i <= remaining; i++) {
      const cell = document.createElement('div');
      cell.className = 'cal-day-cell other-month';
      cell.textContent = String(i).padStart(2, '0');
      grid.appendChild(cell);
    }
  }

  function applyQuickPreset(type) {
    if (type === 'today') {
      calTempStartDate = '2026-02-28';
      calTempEndDate = '2026-02-28';
    } else if (type === '7days') {
      calTempStartDate = '2026-02-22';
      calTempEndDate = '2026-02-28';
    } else if (type === '30days') {
      calTempStartDate = '2026-01-30';
      calTempEndDate = '2026-02-28';
    } else if (type === 'thisMonth') {
      calTempStartDate = '2026-02-01';
      calTempEndDate = '2026-02-28';
    } else if (type === 'all') {
      calTempStartDate = '';
      calTempEndDate = '';
    }

    if (calTempStartDate) {
      const parts = calTempStartDate.split('-');
      calCurrentYear = parseInt(parts[0], 10);
      calCurrentMonth = parseInt(parts[1], 10) - 1;
      syncCalSelectors();
    }
    updateCalHeaderPills();
    renderCalendarGrid();
  }

  function confirmCalendarSelection() {
    const startInput = document.getElementById('filterStartDate');
    const endInput = document.getElementById('filterEndDate');
    const displayLabel = document.getElementById('dateRangeDisplayLabel');
    const clearBtn = document.getElementById('clearDateBtn');

    if (startInput) startInput.value = calTempStartDate;
    if (endInput) endInput.value = calTempEndDate;

    if (calTempStartDate && calTempEndDate) {
      if (displayLabel) displayLabel.textContent = `${formatDisplayDate(calTempStartDate)} - ${formatDisplayDate(calTempEndDate)}`;
      if (clearBtn) clearBtn.style.display = 'flex';
      const monthSelect = document.getElementById('filterMonth');
      if (monthSelect) monthSelect.value = '';
    } else if (calTempStartDate) {
      if (displayLabel) displayLabel.textContent = formatDisplayDate(calTempStartDate);
      if (clearBtn) clearBtn.style.display = 'flex';
      const monthSelect = document.getElementById('filterMonth');
      if (monthSelect) monthSelect.value = '';
    } else {
      if (displayLabel) displayLabel.textContent = 'Semua Tanggal (YTD)';
      if (clearBtn) clearBtn.style.display = 'none';
    }

    closeCalendarModal();
    applyFilters();
  }

  function clearDateRange() {
    calTempStartDate = '';
    calTempEndDate = '';
    const startInput = document.getElementById('filterStartDate');
    const endInput = document.getElementById('filterEndDate');
    const displayLabel = document.getElementById('dateRangeDisplayLabel');
    const clearBtn = document.getElementById('clearDateBtn');

    if (startInput) startInput.value = '';
    if (endInput) endInput.value = '';
    if (displayLabel) displayLabel.textContent = 'Semua Tanggal (YTD)';
    if (clearBtn) clearBtn.style.display = 'none';

    updateCalHeaderPills();
    applyFilters();
  }

  // Instant Client-Side Filter Engine
  function applyFilters() {
    const month = document.getElementById('filterMonth').value;
    const startDate = document.getElementById('filterStartDate') ? document.getElementById('filterStartDate').value : '';
    const endDate = document.getElementById('filterEndDate') ? document.getElementById('filterEndDate').value : '';
    const area = document.getElementById('filterArea').value;
    const outlet = document.getElementById('filterOutlet').value;

    const clearDateBtn = document.getElementById('clearDateBtn');
    if (clearDateBtn) {
      clearDateBtn.style.display = (startDate || endDate) ? 'flex' : 'none';
    }

    currentFilter = { month, startDate, endDate, area, outlet };

    // Update active filter tags
    updateActiveFilterTags();

    if (!RAW_SALES.length) return;

    // Fast Filtering Loop (56k items in < 5ms)
    let s26 = 0, s25 = 0, q26 = 0, q25 = 0;
    const txSet26 = new Set(), txSet25 = new Set();
    
    const byOutlet = {}, byArea = {}, byProduct = {}, byHour = {}, byDay = {}, byMonth = {};
    const hourTx26 = {}, hourTx25 = {};

    for (let i = 0; i < 24; i++) {
      const hStr = String(i).padStart(2, '0');
      byHour[hStr] = { s26: 0, s25: 0 };
      hourTx26[hStr] = new Set();
      hourTx25[hStr] = new Set();
    }

    let itemNetSales26 = 0, itemNetSales25 = 0;

    const startDm = startDate ? startDate.substring(5) : '';
    const endDm = endDate ? endDate.substring(5) : '';
    const selMonth = month ? month.slice(-2) : '';

    for (let i = 0; i < RAW_SALES.length; i++) {
      const r = RAW_SALES[i]; // [year, date, hour, outlet, area, product, qty, net_sales, invoice, item_net_sales]
      const rYear = r[0];
      const rDate = r[1];
      const rMonth = rDate.substring(0, 7);
      const rHour = r[2];
      const rOutlet = r[3];
      const rArea = r[4];
      const rProduct = r[5];
      const rQty = r[6];
      const rSales = r[7];
      const rInvoice = r[8];
      const rItemNetSales = r[9] || 0;
      const rDm = rDate.substring(5);

      // Match filter criteria
      if (startDate || endDate) {
        if (startDm && rDm < startDm) continue;
        if (endDm && rDm > endDm) continue;
      } else if (selMonth) {
        if (rDate.substring(5, 7) !== selMonth) continue;
      }

      if (area && rArea !== area) continue;
      if (outlet && rOutlet !== outlet) continue;

      const txId = rOutlet + '_' + rDate + '_' + rInvoice;
      const mKey = rMonth.substring(5, 7);
      if (!byMonth[mKey]) byMonth[mKey] = { s26: 0, s25: 0 };

      if (rYear === 2026) {
        s26 += rSales;
        itemNetSales26 += rItemNetSales;
        q26 += rQty;
        txSet26.add(txId);

        if (!byOutlet[rOutlet]) byOutlet[rOutlet] = { s26: 0, s25: 0, q26: 0, q25: 0, tx26: new Set(), tx25: new Set(), area: rArea };
        byOutlet[rOutlet].s26 += rSales;
        byOutlet[rOutlet].q26 += rQty;
        byOutlet[rOutlet].tx26.add(txId);

        if (!byArea[rArea]) byArea[rArea] = { s26: 0, s25: 0, q26: 0, q25: 0, tx26: new Set(), tx25: new Set() };
        byArea[rArea].s26 += rSales;
        byArea[rArea].q26 += rQty;
        byArea[rArea].tx26.add(txId);

        if (!byProduct[rProduct]) byProduct[rProduct] = { s26: 0, s25: 0, q26: 0, q25: 0 };
        byProduct[rProduct].s26 += rSales;
        byProduct[rProduct].q26 += rQty;

        if (byHour[rHour]) {
          byHour[rHour].s26 += rSales;
          hourTx26[rHour].add(txId);
        }

        const dayKey = rDate.substring(5);
        if (!byDay[dayKey]) byDay[dayKey] = { s26: 0, s25: 0 };
        byDay[dayKey].s26 += rSales;
        byMonth[mKey].s26 += rSales;

      } else if (rYear === 2025) {
        s25 += rSales;
        itemNetSales25 += rItemNetSales;
        q25 += rQty;
        txSet25.add(txId);

        if (!byOutlet[rOutlet]) byOutlet[rOutlet] = { s26: 0, s25: 0, q26: 0, q25: 0, tx26: new Set(), tx25: new Set(), area: rArea };
        byOutlet[rOutlet].s25 += rSales;
        byOutlet[rOutlet].q25 += rQty;
        byOutlet[rOutlet].tx25.add(txId);

        if (!byArea[rArea]) byArea[rArea] = { s26: 0, s25: 0, q26: 0, q25: 0, tx26: new Set(), tx25: new Set() };
        byArea[rArea].s25 += rSales;
        byArea[rArea].q25 += rQty;
        byArea[rArea].tx25.add(txId);

        if (!byProduct[rProduct]) byProduct[rProduct] = { s26: 0, s25: 0, q26: 0, q25: 0 };
        byProduct[rProduct].s25 += rSales;
        byProduct[rProduct].q25 += rQty;

        if (byHour[rHour]) {
          byHour[rHour].s25 += rSales;
          hourTx25[rHour].add(txId);
        }

        const dayKey = rDate.substring(5);
        if (!byDay[dayKey]) byDay[dayKey] = { s26: 0, s25: 0 };
        byDay[dayKey].s25 += rSales;
        byMonth[mKey].s25 += rSales;
      }
    }

    // Filter Target
    let targetTotal = 0;
    const targetDailyMap = {};
    const targetMonthMap = {};
    for (let i = 0; i < RAW_TARGETS.length; i++) {
      const t = RAW_TARGETS[i];
      const tDm = t.date.substring(5);
      if (startDate || endDate) {
        if (startDm && tDm < startDm) continue;
        if (endDm && tDm > endDm) continue;
      } else if (selMonth) {
        if (t.date.substring(5, 7) !== selMonth) continue;
      }

      if (outlet && t.outlet !== outlet) continue;
      if (area && t.area !== area) continue;

      targetTotal += t.target;
      targetDailyMap[t.date] = (targetDailyMap[t.date] || 0) + t.target;
      const tmKey = t.date.substring(5, 7);
      targetMonthMap[tmKey] = (targetMonthMap[tmKey] || 0) + t.target;
    }

    const tx26Count = txSet26.size;
    const tx25Count = txSet25.size;
    const atv26 = tx26Count > 0 ? (s26 / tx26Count) : 0;
    const atv25 = tx25Count > 0 ? (s25 / tx25Count) : 0;
    const upt26 = tx26Count > 0 ? (q26 / tx26Count) : 0;
    const upt25 = tx25Count > 0 ? (q25 / tx25Count) : 0;

    const growthSales = s25 > 0 ? ((s26 - s25) / s25 * 100) : null;
    const growthTx = tx25Count > 0 ? ((tx26Count - tx25Count) / tx25Count * 100) : null;
    const growthQty = q25 > 0 ? ((q26 - q25) / q25 * 100) : null;
    const growthAtv = atv25 > 0 ? ((atv26 - atv25) / atv25 * 100) : null;

    const targetAchieve = targetTotal > 0 ? (s26 / targetTotal * 100) : 0;
    const targetGap = s26 - targetTotal;

    // Update KPIs in DOM
    document.getElementById('kpiSales2026').textContent = formatRp(s26);
    document.getElementById('kpiSales2025').textContent = formatRp(s25);
    
    const kpiSalesGrowthEl = document.getElementById('kpiSalesGrowth');
    kpiSalesGrowthEl.className = 'badge-growth ' + (growthSales !== null && growthSales >= 0 ? 'positive' : (growthSales !== null ? 'negative' : 'neutral'));
    kpiSalesGrowthEl.textContent = (growthSales !== null ? (growthSales >= 0 ? '+' : '') + growthSales.toFixed(2) + '%' : '-') + ' (' + (s26 - s25 >= 0 ? '+' : '') + formatRp(s26 - s25) + ')';

    document.getElementById('kpiTargetRevenue').textContent = formatRp(targetTotal);
    document.getElementById('kpiTargetAchievement').textContent = targetAchieve.toFixed(2) + '%';
    document.getElementById('kpiTargetProgressFill').style.width = Math.min(targetAchieve, 100) + '%';

    const kpiTargetStatusEl = document.getElementById('kpiTargetStatus');
    kpiTargetStatusEl.className = 'badge-growth ' + (targetGap >= 0 ? 'positive' : 'negative');
    kpiTargetStatusEl.textContent = (targetGap >= 0 ? 'MELAMPAUI TARGET' : 'DEFISIT DARI TARGET') + ' (' + (targetGap >= 0 ? '+' : '') + formatRp(targetGap) + ')';

    document.getElementById('kpiTx2026').textContent = formatNum(tx26Count);
    const kpiTxGrowthEl = document.getElementById('kpiTxGrowth');
    kpiTxGrowthEl.className = 'badge-growth ' + (growthTx !== null && growthTx >= 0 ? 'positive' : 'negative');
    kpiTxGrowthEl.textContent = growthTx !== null ? (growthTx >= 0 ? '+' : '') + growthTx.toFixed(2) + '%' : '-';
    document.getElementById('kpiAtv').textContent = formatRp(atv26);

document.getElementById('kpiQty2026').textContent = formatNum(q26);
    const kpiQtyGrowthEl = document.getElementById('kpiQtyGrowth');
    kpiQtyGrowthEl.className = 'badge-growth ' + (growthQty !== null && growthQty >= 0 ? 'positive' : 'negative');
    kpiQtyGrowthEl.textContent = growthQty !== null ? (growthQty >= 0 ? '+' : '') + growthQty.toFixed(2) + '%' : '-';
    document.getElementById('kpiUpt').textContent = upt26.toFixed(2) + ' item';

    // Outlets Flatten & Sort
    const outletList = Object.entries(byOutlet).map(([name, v]) => ({
      name,
      s26: v.s26,
      s25: v.s25,
      q26: v.q26,
      q25: v.q25,
      tx26: v.tx26.size,
      tx25: v.tx25.size,
      contrib26: s26 > 0 ? (v.s26 / s26 * 100) : 0,
      growthSales: v.s25 > 0 ? ((v.s26 - v.s25) / v.s25 * 100) : null
    })).sort((a, b) => b.s26 - a.s26);

    // Areas Flatten & Sort
    const areaList = Object.entries(byArea).map(([name, v]) => ({
      name,
      s26: v.s26,
      s25: v.s25,
      q26: v.q26,
      q25: v.q25,
      tx26: v.tx26.size,
      tx25: v.tx25.size,
      contrib26: s26 > 0 ? (v.s26 / s26 * 100) : 0,
      growthSales: v.s25 > 0 ? ((v.s26 - v.s25) / v.s25 * 100) : null
    })).sort((a, b) => b.s26 - a.s26);

    // Products Flatten & Sort
    const productList = Object.entries(byProduct).map(([name, v]) => ({
      name,
      s26: v.s26,
      s25: v.s25,
      q26: v.q26,
      q25: v.q25,
      contrib26: s26 > 0 ? (v.s26 / s26 * 100) : 0,
      growthQty: v.q25 > 0 ? ((v.q26 - v.q25) / v.q25 * 100) : null
    })).sort((a, b) => b.s26 - a.s26);

    // Hourly Array (Only active operational hours up to hour 20, excluding 21-23)
    const activeHours = Object.keys(byHour).filter(h => parseInt(h, 10) <= 20 && (byHour[h].s26 > 0 || byHour[h].s25 > 0 || hourTx26[h].size > 0 || hourTx25[h].size > 0)).sort();
    const minH = activeHours.length ? parseInt(activeHours[0], 10) : 8;
    const maxH = Math.min(activeHours.length ? parseInt(activeHours[activeHours.length - 1], 10) : 20, 20);

    const hourlyList = [];
    let maxHourSales = 0, peakHourSales = "16";
    let maxHourTx = 0, peakHourTx = "16";

    for (let i = minH; i <= maxH; i++) {
      const hStr = String(i).padStart(2, '0');
      const s26H = byHour[hStr] ? byHour[hStr].s26 : 0;
      const s25H = byHour[hStr] ? byHour[hStr].s25 : 0;
      const tx26H = hourTx26[hStr] ? hourTx26[hStr].size : 0;
      const tx25H = hourTx25[hStr] ? hourTx25[hStr].size : 0;

      if (s26H > maxHourSales) { maxHourSales = s26H; peakHourSales = hStr; }
      if (tx26H > maxHourTx) { maxHourTx = tx26H; peakHourTx = hStr; }

      hourlyList.push({
        hour: hStr,
        net_sales_2026: s26H,
        net_sales_2025: s25H,
        transactions_2026: tx26H,
        transactions_2025: tx25H
      });
    }

    document.getElementById('peakSalesHour').textContent = 'Pukul ' + peakHourSales + ':00';
    document.getElementById('peakTxHour').textContent = 'Pukul ' + peakHourTx + ':00';

    // Chart 1 & Chart 2 Data (Monthly if YTD/all months with no custom date range; Daily if single month or custom date range selected)
    const mNames = ["", "Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Agu", "Sep", "Okt", "Nov", "Des"];
    const mFullNames = ["", "Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
    const hasDateRange = Boolean(startDate || endDate);
    const isMonthlyView = !selMonth && !hasDateRange; // True only if "Semua Bulan (YTD)" and no date range

    let dailyChartList = [];
    let targetChartList = [];

    const chart1Title = document.getElementById('chart1Title');
    const chart1Subtitle = document.getElementById('chart1Subtitle');
    const chart2Title = document.getElementById('chart2Title');
    const chart2Subtitle = document.getElementById('chart2Subtitle');

    if (isMonthlyView) {
      if (chart1Title) chart1Title.textContent = 'Tren Penjualan Bulanan (2026 vs 2025)';
      if (chart1Subtitle) chart1Subtitle.textContent = 'Perbandingan pergerakan revenue bulanan YTD';
      if (chart2Title) chart2Title.textContent = 'Target vs Realisasi Bulanan 2026';
      if (chart2Subtitle) chart2Subtitle.textContent = 'Monitoring target bulanan vs aktual tercapai YTD';

      const monthKeys = Object.keys(byMonth).sort();
      dailyChartList = monthKeys.map(mKey => {
        const mIdx = parseInt(mKey, 10);
        return {
          date: '2026-' + mKey,
          comparison_date: '2025-' + mKey,
          label: mFullNames[mIdx] || mKey,
          short_label: mNames[mIdx] || mKey,
          is_monthly: true,
          2026: byMonth[mKey].s26,
          2025: byMonth[mKey].s25
        };
      });

      targetChartList = dailyChartList.map(item => {
        const mKey = item.date.substring(5, 7);
        return {
          date: item.date,
          label: item.label,
          short_label: item.short_label,
          is_monthly: true,
          target: targetMonthMap[mKey] || 0,
          actual: item['2026']
        };
      });
    } else {
      if (hasDateRange) {
        const dateRangeLabel = (startDate ? formatDisplayDate(startDate) : 'Awal') + ' - ' + (endDate ? formatDisplayDate(endDate) : 'Akhir');
        if (chart1Title) chart1Title.textContent = `Tren Penjualan Harian (${dateRangeLabel})`;
        if (chart1Subtitle) chart1Subtitle.textContent = `Perbandingan pergerakan revenue harian 2026 vs 2025`;
        if (chart2Title) chart2Title.textContent = `Target vs Realisasi Harian (${dateRangeLabel})`;
        if (chart2Subtitle) chart2Subtitle.textContent = `Monitoring target harian vs aktual tercapai`;
      } else {
        const selMonthIdx = parseInt(selMonth, 10);
        const selMonthName = mFullNames[selMonthIdx] || month;
        if (chart1Title) chart1Title.textContent = `Tren Penjualan Harian (${selMonthName} 2026 vs 2025)`;
        if (chart1Subtitle) chart1Subtitle.textContent = `Perbandingan pergerakan revenue harian bulan ${selMonthName}`;
        if (chart2Title) chart2Title.textContent = `Target vs Realisasi Harian (${selMonthName} 2026)`;
        if (chart2Subtitle) chart2Subtitle.textContent = `Monitoring target harian vs aktual tercapai bulan ${selMonthName}`;
      }

      const dayKeys = Object.keys(byDay).sort();
      dailyChartList = dayKeys.map(dayKey => {
        const parts = dayKey.split('-');
        const dNum = parseInt(parts[1], 10);
        const mLabel = mNames[parseInt(parts[0], 10)] || parts[0];
        return {
          date: '2026-' + dayKey,
          comparison_date: '2025-' + dayKey,
          label: dNum + ' ' + mLabel,
          short_label: dNum + ' ' + mLabel,
          is_monthly: false,
          2026: byDay[dayKey].s26,
          2025: byDay[dayKey].s25
        };
      });

      targetChartList = dailyChartList.map(item => ({
        date: item.date,
        label: item.label,
        short_label: item.short_label,
        is_monthly: false,
        target: targetDailyMap[item.date] || 0,
        actual: item['2026']
      }));
    }

    // Update Top 5 & Bottom 5 in DOM
    const active26Outlets = outletList.filter(o => o.s26 > 0);
    const top5 = active26Outlets.slice(0, 5);
    const bottom5 = [...active26Outlets].reverse().slice(0, 5);

    let topHtml = '';
    top5.forEach((o, idx) => {
      topHtml += `
        <div class="insight-item">
          <div><span class="insight-rank">${idx + 1}</span><span>${o.name}</span></div>
          <strong>${formatRp(o.s26)} <span style="font-size:11px; color:var(--text-muted);">(${o.contrib26.toFixed(1)}%)</span></strong>
        </div>`;
    });
    document.getElementById('topOutletsList').innerHTML = topHtml || '<div class="insight-item">Tidak ada data</div>';

    let bottomHtml = '';
    bottom5.forEach(o => {
      bottomHtml += `
        <div class="insight-item">
          <div><span class="insight-rank" style="background:var(--danger-subtle); color:var(--danger);">!</span><span>${o.name}</span></div>
          <strong>${formatRp(o.s26)} <span class="badge-growth ${o.growthSales !== null && o.growthSales < 0 ? 'negative' : 'neutral'}">${o.growthSales !== null ? (o.growthSales >= 0 ? '+' : '') + o.growthSales.toFixed(1) + '%' : '-'}</span></strong>
        </div>`;
    });
    document.getElementById('bottomOutletsList').innerHTML = bottomHtml || '<div class="insight-item">Tidak ada data</div>';

    // Update Narrative Text
    const growthSalesStr = growthSales !== null ? (growthSales >= 0 ? '+' : '') + growthSales.toFixed(2) + '%' : '0.0%';
    document.getElementById('narrativeText').textContent = 
      `Total penjualan 2026 tercatat sebesar ${formatRp(s26)} (${targetAchieve.toFixed(1)}% dari target ${formatRp(targetTotal)}). ` +
      `Performa penjualan tercatat ${(growthSales || 0) >= 0 ? 'tumbuh' : 'terkoreksi'} ${growthSalesStr} dibanding periode yang sama tahun 2025. ` +
      `Rata-rata transaksi per pelanggan (ATV) adalah ${formatRp(atv26)} dengan puncak penjualan pada pukul ${peakHourSales}:00.`;

    // Update Business Insights Cards (Dynamic Management & Operational Summary)
    updateBusinessInsights({
      s26, s25, q26, q25, tx26Count, tx25Count,
      growthSales, growthQty, growthTx, growthAtv, growthUpt,
      atv26, atv25, upt26, upt25,
      targetTotal, targetAchieve, targetGap,
      outletList, areaList, productList,
      peakHourSales, peakHourTx, hourlyList,
      currentFilter
    });

    // Render Tables in DOM
    renderOutletsTable(outletList);
    renderAreasTable(areaList);
    renderProductsTable(productList);

    // Save data for chart redraw & Excel download
    currentDashboardData = {
      summary: {
        "2026": { net_sales: s26, qty: q26, transactions: tx26Count, atv: atv26, upt: upt26, asp: q26 > 0 ? s26/q26 : 0 },
        "2025": { net_sales: s25, qty: q25, transactions: tx25Count, atv: atv25, upt: upt25, asp: q25 > 0 ? s25/q25 : 0 },
        growth: { net_sales: growthSales, qty: growthQty, transactions: growthTx, atv: growthAtv },
        diff: { net_sales: s26 - s25, qty: q26 - q25, transactions: tx26Count - tx25Count, atv: atv26 - atv25 }
      },
      target_revenue: targetTotal,
      target_achievement: targetAchieve,
      target_gap: targetGap,
      target_status: targetGap >= 0 ? "MELAMPAUI TARGET" : "DEFISIT DARI TARGET",
      outlets: outletList.map(o => ({ name: o.name, "2026": { net_sales: o.s26, qty: o.q26, transactions: o.tx26 }, "2025": { net_sales: o.s25, qty: o.q25 }, contrib_2026: o.contrib26, growth_sales: o.growthSales })),
      areas: areaList.map(a => ({ name: a.name, "2026": { net_sales: a.s26, qty: a.q26, transactions: a.tx26 }, "2025": { net_sales: a.s25, qty: a.q25 }, contrib_2026: a.contrib26, growth_sales: a.growthSales })),
      products: productList.map(p => ({ name: p.name, "2026": { net_sales: p.s26, qty: p.q26 }, "2025": { qty: p.q25, net_sales: p.s25 }, contrib_2026: p.contrib26, growth_qty: p.growthQty })),
      daily_chart: dailyChartList,
      target_chart: targetChartList,
      hourly_chart: hourlyList,
      peak_sales_hour: peakHourSales,
      peak_tx_hour: peakHourTx,
      executive_narrative: document.getElementById('narrativeText').textContent
    };

    // Redraw charts
    redrawAllCharts();
  }

  function updateActiveFilterTags() {
    const container = document.getElementById('activeFiltersContainer');
    const tagsEl = document.getElementById('activeFilterTags');
    const parts = [];

    if (currentFilter.month) parts.push(`Bulan: ${MONTH_NAMES[currentFilter.month] || currentFilter.month}`);
    if (currentFilter.startDate && currentFilter.endDate) {
      parts.push(`Tanggal: ${formatDisplayDate(currentFilter.startDate)} s/d ${formatDisplayDate(currentFilter.endDate)}`);
    } else if (currentFilter.startDate) {
      parts.push(`Dari: ${formatDisplayDate(currentFilter.startDate)}`);
    } else if (currentFilter.endDate) {
      parts.push(`Sampai: ${formatDisplayDate(currentFilter.endDate)}`);
    }
    if (currentFilter.area) parts.push(`Area: ${currentFilter.area}`);
    if (currentFilter.outlet) parts.push(`Outlet: ${currentFilter.outlet}`);

    if (parts.length) {
      container.style.display = 'flex';
      tagsEl.innerHTML = parts.map(p => `<span class="filter-tag">${p}</span>`).join(' ');
    } else {
      container.style.display = 'none';
      tagsEl.innerHTML = '';
    }
  }

  function resetFilters() {
    document.getElementById('filterMonth').value = '';
    const startEl = document.getElementById('filterStartDate');
    const endEl = document.getElementById('filterEndDate');
    if (startEl) startEl.value = '';
    const clearBtn = document.getElementById('clearDateBtn');
    if (clearBtn) clearBtn.style.display = 'none';
    document.getElementById('filterArea').value = '';
    document.getElementById('filterOutlet').value = '';
    onAreaChange(); // This will reset outlet dropdown and call applyFilters()
  }

  function updateBusinessInsights(params) {
    const {
      s26, s25, q26, q25, tx26Count, tx25Count,
      growthSales, growthQty, growthTx, growthAtv, growthUpt,
      atv26, atv25, upt26, upt25,
      targetTotal, targetAchieve, targetGap,
      outletList, areaList, productList,
      peakHourSales, peakHourTx, hourlyList,
      currentFilter
    } = params;

    const healthBadge = document.getElementById('insightHealthBadge');
    const healthText = document.getElementById('insightHealthText');
    const subtitleEl = document.getElementById('insightPeriodSubtitle');

    // Filter subtitle description
    let filterDesc = 'Semua Data (YTD 2026)';
    if (currentFilter.startDate && currentFilter.endDate) {
      filterDesc = `Rentang Tanggal: ${formatDisplayDate(currentFilter.startDate)} s/d ${formatDisplayDate(currentFilter.endDate)}`;
    } else if (currentFilter.startDate) {
      filterDesc = `Sejak: ${formatDisplayDate(currentFilter.startDate)}`;
    } else if (currentFilter.month) {
      filterDesc = `Bulan: ${MONTH_NAMES[currentFilter.month] || currentFilter.month}`;
    }
    if (currentFilter.area) filterDesc += ` | Area: ${currentFilter.area}`;
    if (currentFilter.outlet) filterDesc += ` | Outlet: ${currentFilter.outlet}`;
    if (subtitleEl) subtitleEl.textContent = `Analisis pintar otomatis untuk: ${filterDesc}`;

    // Overall Health Status
    if (healthBadge && healthText) {
      healthBadge.className = 'insight-health-status';
      if (targetAchieve >= 100 && (growthSales || 0) >= 0) {
        healthBadge.classList.add('positive');
        healthText.textContent = `🟢 Performa Prima (Target ${targetAchieve.toFixed(1)}% | Tumbuh YoY)`;
      } else if ((growthSales || 0) >= 0) {
        healthBadge.classList.add('positive');
        healthText.textContent = `🟢 Tumbuh Positif (+${(growthSales||0).toFixed(1)}% YoY)`;
      } else if ((growthSales || 0) >= -10) {
        healthBadge.classList.add('warning');
        healthText.textContent = `🟡 Waspada Penurunan (${(growthSales||0).toFixed(1)}% YoY)`;
      } else {
        healthBadge.classList.add('danger');
        healthText.textContent = `🔴 Perlu Intervensi Taktis (${(growthSales||0).toFixed(1)}% YoY)`;
      }
    }

    // Card 1: Revenue Health & Target
    const revTitle = document.getElementById('bizRevenueTitle');
    const revContent = document.getElementById('bizRevenueContent');
    if (revTitle) revTitle.textContent = `${formatRp(s26)} (${(growthSales !== null && growthSales >= 0 ? '+' : '') + (growthSales || 0).toFixed(1)}% YoY)`;

    const diffSales = s26 - s25;
    const targetStatusText = targetGap >= 0 
      ? `Surplus <strong style="color:var(--success);">+${formatRp(targetGap)}</strong> di atas budget target.`
      : `Kurang <strong style="color:var(--danger);">${formatRp(Math.abs(targetGap))}</strong> untuk mencapai 100% target.`;

    let card1Html = `
      <div class="biz-point">
        <span class="biz-point-tag ${diffSales >= 0 ? 'growth' : 'drop'}">${diffSales >= 0 ? '▲ YoY' : '▼ YoY'}</span>
        <div class="biz-point-text">
          Realisasi omset 2026 tercatat <strong>${formatRp(s26)}</strong> dibanding <strong>${formatRp(s25)}</strong> di 2025 (${diffSales >= 0 ? 'tumbuh +' : 'turun '}${formatRp(Math.abs(diffSales))}).
        </div>
      </div>
      <div class="biz-point">
        <span class="biz-point-tag target">Target</span>
        <div class="biz-point-text">
          Tercapai <strong>${targetAchieve.toFixed(1)}%</strong> dari target <strong>${formatRp(targetTotal)}</strong>. ${targetStatusText}
        </div>
      </div>
    `;
    if (revContent) revContent.innerHTML = card1Html;

    // Card 2: Customer Basket & Ticket Size
    const basketTitle = document.getElementById('bizBasketTitle');
    const basketContent = document.getElementById('bizBasketContent');
    if (basketTitle) basketTitle.textContent = `ATV ${formatRp(atv26)} | UPT ${upt26.toFixed(2)} item`;

    const atvDiff = atv26 - atv25;
    const isTrafficDriver = (growthTx || 0) > (growthAtv || 0);

    let card2Html = `
      <div class="biz-point">
        <span class="biz-point-tag driver">Keranjang</span>
        <div class="biz-point-text">
          Rata-rata belanja per struk (ATV) <strong>${formatRp(atv26)}</strong> (${atvDiff >= 0 ? 'naik +' : 'turun '}${formatRp(Math.abs(atvDiff))} / ${(growthAtv||0).toFixed(1)}% YoY).
        </div>
      </div>
      <div class="biz-point">
        <span class="biz-point-tag ${isTrafficDriver ? 'growth' : 'action'}">${isTrafficDriver ? 'Traffic' : 'Ticket Size'}</span>
        <div class="biz-point-text">
          Total <strong>${tx26Count.toLocaleString('id-ID')} struk</strong> (${(growthTx||0) >= 0 ? '+' : ''}${(growthTx||0).toFixed(1)}% YoY). Pertumbuhan omset saat ini didorong oleh <strong>${isTrafficDriver ? 'peningkatan volume transaksi/pelanggan' : 'kenaikan rata-rata nilai belanja per struk'}</strong>.
        </div>
      </div>
    `;
    if (basketContent) basketContent.innerHTML = card2Html;

    // Card 3: Top Performers & Focus Units
    const outletTitle = document.getElementById('bizOutletTitle');
    const outletContent = document.getElementById('bizOutletContent');
    const activeOutlets = outletList.filter(o => o.s26 > 0);
    if (outletTitle) outletTitle.textContent = `${activeOutlets.length} Konter Aktif Beroperasi`;

    const topOutlet = activeOutlets.length ? activeOutlets[0] : null;
    const growthOutlets = [...activeOutlets].filter(o => o.s25 > 0 && o.growthSales !== null).sort((a, b) => b.growthSales - a.growthSales);
    const starGrowthOutlet = growthOutlets.length ? growthOutlets[0] : null;
    const laggingOutlet = growthOutlets.length ? growthOutlets[growthOutlets.length - 1] : null;

    let card3Html = '';
    if (topOutlet) {
      card3Html += `
        <div class="biz-point">
          <span class="biz-point-tag star">Top Outlet</span>
          <div class="biz-point-text">
            <strong>${topOutlet.name}</strong> (${topOutlet.area}) memimpin dengan omset <strong>${formatRp(topOutlet.s26)}</strong> (kontribusi <strong>${topOutlet.contrib26.toFixed(1)}%</strong>).
          </div>
        </div>
      `;
    }
    if (starGrowthOutlet && starGrowthOutlet.growthSales > 0 && starGrowthOutlet.name !== (topOutlet ? topOutlet.name : '')) {
      card3Html += `
        <div class="biz-point">
          <span class="biz-point-tag growth">Fastest</span>
          <div class="biz-point-text">
            Pertumbuhan tertinggi diraih <strong>${starGrowthOutlet.name}</strong> (+${starGrowthOutlet.growthSales.toFixed(1)}% YoY).
          </div>
        </div>
      `;
    } else if (laggingOutlet && laggingOutlet.growthSales < 0) {
      card3Html += `
        <div class="biz-point">
          <span class="biz-point-tag drop">Perhatian</span>
          <div class="biz-point-text">
            <strong>${laggingOutlet.name}</strong> mengalami koreksi omset (${laggingOutlet.growthSales.toFixed(1)}% YoY). Perlu evaluasi display dan promo lokal.
          </div>
        </div>
      `;
    }
    if (outletContent) outletContent.innerHTML = card3Html || '<div class="biz-point">Tidak ada data unit</div>';

    // Card 4: Operating Hours & Key Action Items
    const actionTitle = document.getElementById('bizActionTitle');
    const actionContent = document.getElementById('bizActionContent');
    if (actionTitle) actionTitle.textContent = `Puncak Jam ${peakHourSales}:00 & Rekomendasi`;

    let actionRecommendation = '';
    if (upt26 < 1.5) {
      actionRecommendation = 'UPT berada di angka <1.5 item/struk. Terapkan strategi purchase with purchase (PWP) atau bundling 2-item hemat di kasir.';
    } else if (targetAchieve < 90) {
      actionRecommendation = 'Pencapaian target <90%. Maksimalkan push promo dan ketersediaan stok produk terlaris pada jam sibuk.';
    } else {
      actionRecommendation = 'Performa penjualan solid. Jaga konsistensi stok SKU unggulan dan pertahankan standar pelayanan tim sales.';
    }

    let card4Html = `
      <div class="biz-point">
        <span class="biz-point-tag star">Peak Hour</span>
        <div class="biz-point-text">
          Jam tersibuk penjualan terkonsentrasi pada pukul <strong>${peakHourSales}:00</strong> dan struk terbanyak pada pukul <strong>${peakHourTx}:00</strong>.
        </div>
      </div>
      <div class="biz-point">
        <span class="biz-point-tag action">Aksi Taktis</span>
        <div class="biz-point-text">
          ${actionRecommendation}
        </div>
      </div>
    `;
    if (actionContent) actionContent.innerHTML = card4Html;
  }

  // Render Table DOMs
  function renderOutletsTable(list) {
    const tbody = document.getElementById('outletsTableBody');
    const maxSales = list.length ? Math.max(...list.map(x => x.s26), 1) : 1;
    let html = '';
    list.forEach((o, i) => {
      const gw = o.growthSales;
      const gwBadge = gw !== null ? (gw >= 0 ? '+' : '') + gw.toFixed(1) + '%' : '-';
      const gwClass = gw !== null && gw >= 0 ? 'positive' : (gw !== null ? 'negative' : 'neutral');
      const barPct = (o.s26 / maxSales * 100).toFixed(1);
      html += `
        <tr>
          <td class="text-center" style="color:var(--text-muted);">${i + 1}</td>
          <td style="font-weight:600;">${o.name}</td>
          <td class="text-right">
            <div class="bar-container">
              <div class="data-bar" style="width: ${barPct}%;"></div>
              <span class="bar-value">${formatRp(o.s26)}</span>
            </div>
          </td>
          <td class="text-right"><strong>${o.contrib26.toFixed(1)}%</strong></td>
          <td class="text-right">${formatNum(o.q26)}</td>
          <td class="text-right">${formatNum(o.tx26)}</td>
          <td class="text-right" style="color:var(--text-muted);">${formatRp(o.s25)}</td>
          <td class="text-right"><span class="badge-growth ${gwClass}">${gwBadge}</span></td>
        </tr>`;
    });
    tbody.innerHTML = html;
  }

