  // Product Synonyms Dictionary for natural / keyword searching
  const PRODUCT_SYNONYMS = {
    'sandal': ['sandal', 'sndl', 'sendal'],
    'sndl': ['sandal', 'sndl', 'sendal'],
    'jas': ['jas', 'hujan', 'raincoat'],
    'hujan': ['jas', 'hujan'],
    'botol': ['botol', 'btl', 'prima', 'drink'],
    'btl': ['botol', 'btl'],
    'prima': ['prima', '600ml'],
    'tas': ['tas', 'spunbond', 'bag', 'tote'],
    'spunbond': ['spunbond', 'tas'],
    'case': ['case', 'casing', 'waterproof'],
    'casing': ['case', 'casing', 'waterproof'],
    'waterproof': ['waterproof', 'case'],
    'celana': ['celana', 'cln', 'pant', 'pants', 'boxer'],
    'cln': ['celana', 'cln'],
    'baju': ['baju', 'kaos', 't-shirt', 'hoodie', 'shirt'],
    'hoodie': ['hoodie', 'sweater', 'jaket'],
    'topi': ['topi', 'tp', 'cap', 'hat'],
    'tp': ['topi', 'tp'],
    'payung': ['payung', 'pyg'],
    'kacamata': ['kacamata', 'kcm', 'glasses', 'sunglasses'],
    'boneka': ['bnk', 'boneka', 'doll', 'plush'],
    'bnk': ['bnk', 'boneka']
  };

  function matchProductKeyword(productName, queryTokens) {
    if (!queryTokens.length) return true;
    const lowerName = productName.toLowerCase();

    // Every token in query must match either literally or through synonym groups
    return queryTokens.every(token => {
      if (lowerName.includes(token)) return true;
      const syns = PRODUCT_SYNONYMS[token];
      if (syns && syns.some(s => lowerName.includes(s))) return true;
      return false;
    });
  }

  function renderProductsTable(allProducts) {
    const tbody = document.getElementById('productsTableBody');
    const limitSelect = document.getElementById('productLimitSelect');
    const limitVal = limitSelect ? limitSelect.value : '10';
    const rawQuery = (document.getElementById('tableSearchInput') ? document.getElementById('tableSearchInput').value : '').toLowerCase().trim();
    const summaryEl = document.getElementById('productSearchSummary');
    const statsEl = document.getElementById('productSearchStats');

    // Filter products by keyword query
    const queryTokens = rawQuery.split(/\s+/).filter(Boolean);
    let filtered = allProducts || [];

    if (queryTokens.length > 0) {
      filtered = filtered.filter(p => matchProductKeyword(p.name, queryTokens));
    }

    // Calculate totals of filtered products for context
    const totalDashboardSales = currentDashboardData.summary && currentDashboardData.summary["2026"] ? currentDashboardData.summary["2026"].net_sales : 1;
    const filteredTotalSales = filtered.reduce((acc, p) => acc + (p.s26 !== undefined ? p.s26 : (p["2026"] ? p["2026"].net_sales : 0)), 0);
    const filteredTotalQty = filtered.reduce((acc, p) => acc + (p.q26 !== undefined ? p.q26 : (p["2026"] ? p["2026"].qty : 0)), 0);
    const filteredContrib = totalDashboardSales > 0 ? (filteredTotalSales / totalDashboardSales * 100) : 0;

    if (queryTokens.length > 0 && summaryEl) {
      summaryEl.style.display = 'flex';
      statsEl.innerHTML = `Ditemukan <strong>${filtered.length}</strong> produk mengandung kata kunci "<em>${rawQuery}</em>" | Total Omset: <strong>${formatRp(filteredTotalSales)}</strong> (${filteredContrib.toFixed(1)}% dari total) | Total Qty: <strong>${formatNum(filteredTotalQty)} Pcs</strong>`;
    } else if (summaryEl) {
      summaryEl.style.display = 'none';
    }

    // Slice by selected limit
    let displayed = filtered;
    if (limitVal !== 'all') {
      displayed = filtered.slice(0, parseInt(limitVal, 10));
    }

    const maxSales = displayed.length ? Math.max(...displayed.map(x => (x.s26 !== undefined ? x.s26 : (x["2026"] ? x["2026"].net_sales : 0))), 1) : 1;

    if (!displayed.length) {
      tbody.innerHTML = `<tr><td colspan="7" class="text-center" style="padding:28px 16px; color:var(--text-muted);">Tidak ada produk yang cocok dengan kata kunci "<strong>${rawQuery}</strong>".<br><span style="font-size:12px;">Tips: Coba ketik kata kunci umum seperti <em>jas, sandal, prima, botol, casing, topi</em>.</span></td></tr>`;
      return;
    }

    let html = '';
    displayed.forEach((p, i) => {
      const s26 = p.s26 !== undefined ? p.s26 : (p["2026"] ? p["2026"].net_sales : 0);
      const q26 = p.q26 !== undefined ? p.q26 : (p["2026"] ? p["2026"].qty : 0);
      const q25 = p.q25 !== undefined ? p.q25 : (p["2025"] ? p["2025"].qty : 0);
      const contrib = p.contrib26 !== undefined ? p.contrib26 : (p.contrib_2026 || (totalDashboardSales > 0 ? s26 / totalDashboardSales * 100 : 0));
      const gq = p.growthQty !== undefined ? p.growthQty : (p.growth_qty !== undefined ? p.growth_qty : (q25 > 0 ? (q26 - q25)/q25 * 100 : null));

      const gqBadge = gq !== null ? (gq >= 0 ? '+' : '') + gq.toFixed(1) + '%' : '-';
      const gqClass = gq !== null && gq >= 0 ? 'positive' : (gq !== null ? 'negative' : 'neutral');
      const barPct = (s26 / maxSales * 100).toFixed(1);

      // Highlight query tokens in product name
      let highlightedName = p.name;
      if (queryTokens.length > 0) {
        queryTokens.forEach(tok => {
          const regex = new RegExp(`(${tok})`, 'gi');
          highlightedName = highlightedName.replace(regex, '<mark class="search-highlight">$1</mark>');
        });
      }

      html += `
        <tr>
          <td class="text-center" style="color:var(--text-muted);">${i + 1}</td>
          <td style="font-weight:600;">${highlightedName}</td>
          <td class="text-right">
            <div class="bar-container">
              <div class="data-bar" style="width: ${barPct}%;"></div>
              <span class="bar-value">${formatRp(s26)}</span>
            </div>
          </td>
          <td class="text-right"><strong>${contrib.toFixed(1)}%</strong></td>
          <td class="text-right">${formatNum(q26)}</td>
          <td class="text-right" style="color:var(--text-muted);">${formatNum(q25)}</td>
          <td class="text-right"><span class="badge-growth ${gqClass}">${gqBadge}</span></td>
        </tr>`;
    });
    tbody.innerHTML = html;
  }

  // ----------------------------------------------------
  // DOWNLOAD EXCEL (.xlsx) ENGINE
  // ----------------------------------------------------
  function downloadCuratedExcel() {
    // Check if on Flask server
    if (window.location.protocol.startsWith('http')) {
      const params = new URLSearchParams();
      if (currentFilter.month) params.set('month', currentFilter.month);
      if (currentFilter.startDate) params.set('start_date', currentFilter.startDate);
      if (currentFilter.endDate) params.set('end_date', currentFilter.endDate);
      if (currentFilter.area) params.set('area', currentFilter.area);
      if (currentFilter.outlet) params.set('outlet', currentFilter.outlet);
      window.location.href = '/download?' + params.toString();
      return;
    }

    // Client-side SheetJS Export (Works 100% Offline in Static HTML)
    if (typeof XLSX === 'undefined') {
      alert('Sedang memuat engine Excel, silakan coba 2 detik lagi...');
      return;
    }

    const d = currentDashboardData;
    const wb = XLSX.utils.book_new();

    // 1. Sheet: Ringkasan KPI
    const kpiData = [
      ["SALES PERFORMANCE & GROWTH REPORT"],
      ["Filter: " + (Object.values(currentFilter).filter(Boolean).join(" - ") || "Semua Data")],
      ["Diunduh: " + new Date().toLocaleString('id-ID')],
      [],
      ["RINGKASAN EKSEKUTIF:"],
      [d.executive_narrative],
      [],
      ["Indikator / Metrik", "Tahun 2026 (Utama)", "Tahun 2025 (Pembanding)", "Pertumbuhan YoY (%)", "Selisih (+/-)"],
      ["Net Sales (Omset)", d.summary["2026"].net_sales, d.summary["2025"].net_sales, (d.summary.growth.net_sales || 0) + '%', d.summary.diff.net_sales],
      ["Target Revenue 2026", d.target_revenue, "-", "-", d.target_gap],
      ["Pencapaian Target (%)", d.target_achievement.toFixed(2) + '%', "-", "-", "-"],
      ["Total Transaksi (Struk)", d.summary["2026"].transactions, d.summary["2025"].transactions, (d.summary.growth.transactions || 0) + '%', d.summary.diff.transactions],
      ["Total Qty Terjual (Pcs)", d.summary["2026"].qty, d.summary["2025"].qty, (d.summary.growth.qty || 0) + '%', d.summary.diff.qty],
      ["ATV (Rata-rata/Struk)", d.summary["2026"].atv, d.summary["2025"].atv, (d.summary.growth.atv || 0) + '%', d.summary.diff.atv],
      ["UPT (Item/Struk)", d.summary["2026"].upt, d.summary["2025"].upt, "-", "-"]
    ];
    const wsKpi = XLSX.utils.aoa_to_sheet(kpiData);
    XLSX.utils.book_append_sheet(wb, wsKpi, "Ringkasan KPI");

    // 2. Sheet: Performa Outlet
    const outletData = [
      ["Rank", "Nama Konter / Outlet", "Net Sales 2026", "Kontribusi (%)", "Qty 2026", "Transaksi 2026", "Net Sales 2025", "Growth Sales (%)"]
    ];
    d.outlets.forEach((o, i) => {
      outletData.push([
        i + 1, o.name, o["2026"].net_sales, o.contrib_2026 ? o.contrib_2026.toFixed(1) + '%' : '0%',
        o["2026"].qty, o["2026"].transactions, o["2025"].net_sales, o.growth_sales !== null ? o.growth_sales.toFixed(1) + '%' : '-'
      ]);
    });
    const wsOutlet = XLSX.utils.aoa_to_sheet(outletData);
    XLSX.utils.book_append_sheet(wb, wsOutlet, "Performa Outlet");

    // 3. Sheet: Performa Area
    const areaData = [
      ["Rank", "Nama Area", "Net Sales 2026", "Kontribusi (%)", "Qty 2026", "Transaksi 2026", "Net Sales 2025", "Growth Sales (%)"]
    ];
    d.areas.forEach((a, i) => {
      areaData.push([
        i + 1, a.name, a["2026"].net_sales, a.contrib_2026 ? a.contrib_2026.toFixed(1) + '%' : '0%',
        a["2026"].qty, a["2026"].transactions, a["2025"].net_sales, a.growth_sales !== null ? a.growth_sales.toFixed(1) + '%' : '-'
      ]);
    });
    const wsArea = XLSX.utils.aoa_to_sheet(areaData);
    XLSX.utils.book_append_sheet(wb, wsArea, "Performa Area");

    // 4. Sheet: Top Produk
    const prodData = [
      ["Rank", "Nama Barang / Produk", "Net Sales 2026", "Kontribusi (%)", "Qty 2026", "Qty 2025", "Growth Qty (%)"]
    ];
    d.products.slice(0, 200).forEach((p, i) => {
      prodData.push([
        i + 1, p.name, p["2026"].net_sales, p.contrib_2026 ? p.contrib_2026.toFixed(1) + '%' : '0%',
        p["2026"].qty, p["2025"].qty, p.growth_qty !== null ? p.growth_qty.toFixed(1) + '%' : '-'
      ]);
    });
    const wsProd = XLSX.utils.aoa_to_sheet(prodData);
    XLSX.utils.book_append_sheet(wb, wsProd, "Top Produk");

    // 5. Sheet: Performa Jam
    const hrData = [
      ["Jam Operasional", "Net Sales 2026", "Transaksi 2026", "Net Sales 2025", "Transaksi 2025"]
    ];
    d.hourly_chart.forEach(h => {
      hrData.push([`Pukul ${h.hour}:00`, h.net_sales_2026, h.transactions_2026, h.net_sales_2025, h.transactions_2025]);
    });
    const wsHr = XLSX.utils.aoa_to_sheet(hrData);
    XLSX.utils.book_append_sheet(wb, wsHr, "Performa Jam");

    const fileSuffix = Object.values(currentFilter).filter(Boolean).join('_') || 'Semua';
    XLSX.writeFile(wb, `Laporan_Sales_${fileSuffix}.xlsx`);
  }

  // ----------------------------------------------------
  // CHARTS RENDERING ENGINE
  // ----------------------------------------------------
  function redrawAllCharts() {
    drawDailySalesChart();
    drawTargetChart();
    drawHourlySalesChart();
    drawHourlyTxChart();
  }

  // Chart 1: YoY Daily Sales
  const salesCanvas = document.getElementById('salesChart');
  const salesTooltip = document.getElementById('chartTooltip');
  let salesPoints = [];

  function drawDailySalesChart() {
    if (!salesCanvas) return;
    const isDark = root.classList.contains('dark');
    const gridColor = isDark ? '#1f2937' : '#e2e8f0';
    const textColor = isDark ? '#94a3b8' : '#64748b';

    const box = salesCanvas.parentElement;
    const ratio = window.devicePixelRatio || 1;
    const width = box.clientWidth;
    const height = 320;
    salesCanvas.width = width * ratio;
    salesCanvas.height = height * ratio;
    salesCanvas.style.height = height + 'px';

    const ctx = salesCanvas.getContext('2d');
    ctx.scale(ratio, ratio);

    const dailyData = currentDashboardData.daily_chart || [];
    if (!dailyData.length) {
      ctx.fillStyle = textColor;
      ctx.textAlign = 'center';
      ctx.font = '13px sans-serif';
      ctx.fillText('Tidak ada data harian untuk filter ini', width / 2, height / 2);
      return;
    }

    const maxVal = Math.max(...dailyData.flatMap(x => [x['2026'], x['2025']]), 1000000);
    const left = 68, bottom = 36, top = 20, right = 16;
    const plotW = width - left - right;
    const plotH = height - top - bottom;

    ctx.font = '11px sans-serif';
    ctx.fillStyle = textColor;
    ctx.strokeStyle = gridColor;
    ctx.lineWidth = 1;

    [0, 0.25, 0.5, 0.75, 1].forEach(t => {
      const y = top + plotH * (1 - t);
      ctx.beginPath();
      ctx.moveTo(left, y);
      ctx.lineTo(width - right, y);
      ctx.stroke();
      ctx.textAlign = 'left';
      ctx.fillText('Rp ' + Math.round(maxVal * t / 1000000) + 'jt', 6, y + 4);
    });

    const step = plotW / Math.max(dailyData.length - 1, 1);
    salesPoints = [];

    // Series 2025
    ctx.strokeStyle = '#a78bfa';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    dailyData.forEach((item, i) => {
      const x = left + i * step;
      const y = top + plotH - (item['2025'] / maxVal) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Series 2026
    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 3;
    ctx.beginPath();
    dailyData.forEach((item, i) => {
      const x = left + i * step;
      const y = top + plotH - (item['2026'] / maxVal) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      salesPoints.push({ x, y, item });
    });
    ctx.stroke();

    // Markers
    dailyData.forEach((item, i) => {
      const x = left + i * step;
      const y26 = top + plotH - (item['2026'] / maxVal) * plotH;
      ctx.fillStyle = '#2563eb';
      ctx.beginPath();
      ctx.arc(x, y26, 4, 0, Math.PI * 2);
      ctx.fill();
    });

    // Labels
    ctx.fillStyle = textColor;
    ctx.textAlign = 'center';
    ctx.font = '11px sans-serif';
    dailyData.forEach((item, i) => {
      const lbl = item.is_monthly ? (item.short_label || item.label) : item.label;
      if (dailyData.length <= 12) {
        ctx.fillText(lbl, left + i * step, height - 10);
      } else {
        if (i === 0 || i === dailyData.length - 1 || i % Math.ceil(dailyData.length / 10) === 0) {
          ctx.fillText(lbl, left + i * step, height - 10);
        }
      }
    });
  }

  salesCanvas.addEventListener('mousemove', function(e) {
    if (!salesPoints.length) return;
    const rect = salesCanvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    let nearest = salesPoints.reduce((a, p) => Math.hypot(p.x - x, p.y - y) < Math.hypot(a.x - x, a.y - y) ? p : a);
    if (Math.hypot(nearest.x - x, nearest.y - y) < 30) {
      const it = nearest.item;
      const diff = it['2026'] - it['2025'];
      const growth = it['2025'] > 0 ? ((diff / it['2025']) * 100).toFixed(1) + '%' : '-';

      salesTooltip.style.display = 'block';
      salesTooltip.style.left = Math.min(nearest.x + 12, salesCanvas.clientWidth - 230) + 'px';
      salesTooltip.style.top = Math.max(nearest.y - 110, 10) + 'px';
      salesTooltip.innerHTML = `
        <div class="tooltip-title">${it.label} ${it.is_monthly ? '2026 (Bulanan)' : '2026'}</div>
        <div class="tooltip-row"><span class="tooltip-label" style="color:#60a5fa;">● 2026 (Utama):</span> <span class="tooltip-val">${formatRp(it['2026'])}</span></div>
        <div class="tooltip-row"><span class="tooltip-label" style="color:#c4b5fd;">● 2025 (Pembanding):</span> <span class="tooltip-val">${formatRp(it['2025'])}</span></div>
        <div class="tooltip-row"><span class="tooltip-label">YoY Growth:</span> <span class="tooltip-val" style="color:${diff >= 0 ? '#34d399' : '#f87171'}">${growth} (${diff >= 0 ? '+' : ''}${formatRp(diff)})</span></div>
      `;
    } else {
      salesTooltip.style.display = 'none';
    }
  });
  salesCanvas.addEventListener('mouseleave', () => salesTooltip.style.display = 'none');

  // Chart 2: Target vs Actual
  const targetCanvas = document.getElementById('targetChart');
  const targetTooltip = document.getElementById('targetTooltip');
  let targetPoints = [];

  function drawTargetChart() {
    if (!targetCanvas) return;
    const isDark = root.classList.contains('dark');
    const gridColor = isDark ? '#1f2937' : '#e2e8f0';
    const textColor = isDark ? '#94a3b8' : '#64748b';

    const box = targetCanvas.parentElement;
    const ratio = window.devicePixelRatio || 1;
    const width = box.clientWidth;
    const height = 320;
    targetCanvas.width = width * ratio;
    targetCanvas.height = height * ratio;
    targetCanvas.style.height = height + 'px';

    const ctx = targetCanvas.getContext('2d');
    ctx.scale(ratio, ratio);

    const targetData = currentDashboardData.target_chart || [];
    if (!targetData.length) {
      ctx.fillStyle = textColor;
      ctx.textAlign = 'center';
      ctx.fillText('Tidak ada data target', width / 2, height / 2);
      return;
    }

    const maxVal = Math.max(...targetData.flatMap(x => [x.target, x.actual]), 1000000);
    const left = 68, bottom = 36, top = 20, right = 16;
    const plotW = width - left - right;
    const plotH = height - top - bottom;

    ctx.font = '11px sans-serif';
    ctx.fillStyle = textColor;
    ctx.strokeStyle = gridColor;
    ctx.lineWidth = 1;

    [0, 0.25, 0.5, 0.75, 1].forEach(t => {
      const y = top + plotH * (1 - t);
      ctx.beginPath();
      ctx.moveTo(left, y);
      ctx.lineTo(width - right, y);
      ctx.stroke();
      ctx.textAlign = 'left';
      ctx.fillText('Rp ' + Math.round(maxVal * t / 1000000) + 'jt', 6, y + 4);
    });

    const step = plotW / Math.max(targetData.length - 1, 1);
    targetPoints = [];

    // Target Line (Amber)
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    targetData.forEach((item, i) => {
      const x = left + i * step;
      const y = top + plotH - (item.target / maxVal) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Actual Line (Emerald)
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 3;
    ctx.beginPath();
    targetData.forEach((item, i) => {
      const x = left + i * step;
      const y = top + plotH - (item.actual / maxVal) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      targetPoints.push({ x, y, item });
    });
    ctx.stroke();

    // Markers
    targetData.forEach((item, i) => {
      const x = left + i * step;
      const y = top + plotH - (item.actual / maxVal) * plotH;
      ctx.fillStyle = '#10b981';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });

    // Labels
    ctx.fillStyle = textColor;
    ctx.textAlign = 'center';
    ctx.font = '11px sans-serif';
    targetData.forEach((item, i) => {
      const lbl = item.is_monthly ? (item.short_label || item.label) : item.label;
      if (targetData.length <= 12) {
        ctx.fillText(lbl, left + i * step, height - 10);
      } else {
        if (i === 0 || i === targetData.length - 1 || i % Math.ceil(targetData.length / 10) === 0) {
          ctx.fillText(lbl, left + i * step, height - 10);
        }
      }
    });
  }

  targetCanvas.addEventListener('mousemove', function(e) {
    if (!targetPoints.length) return;
    const rect = targetCanvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    let nearest = targetPoints.reduce((a, p) => Math.hypot(p.x - x, p.y - y) < Math.hypot(a.x - x, a.y - y) ? p : a);
    if (Math.hypot(nearest.x - x, nearest.y - y) < 30) {
      const it = nearest.item;
      const achieve = it.target > 0 ? ((it.actual / it.target) * 100).toFixed(1) + '%' : '-';
      const gap = it.actual - it.target;

      targetTooltip.style.display = 'block';
      targetTooltip.style.left = Math.min(nearest.x + 12, targetCanvas.clientWidth - 230) + 'px';
      targetTooltip.style.top = Math.max(nearest.y - 110, 10) + 'px';
      targetTooltip.innerHTML = `
        <div class="tooltip-title">${it.label} ${it.is_monthly ? '2026 (Bulanan)' : '2026'}</div>
        <div class="tooltip-row"><span class="tooltip-label" style="color:#fbbf24;">● Target Revenue:</span> <span class="tooltip-val">${formatRp(it.target)}</span></div>
        <div class="tooltip-row"><span class="tooltip-label" style="color:#34d399;">● Realisasi Sales:</span> <span class="tooltip-val">${formatRp(it.actual)}</span></div>
        <div class="tooltip-row"><span class="tooltip-label">Pencapaian:</span> <span class="tooltip-val" style="color:${gap >= 0 ? '#34d399' : '#f87171'}">${achieve} (${gap >= 0 ? '+' : ''}${formatRp(gap)})</span></div>
      `;
    } else {
      targetTooltip.style.display = 'none';
    }
  });
  targetCanvas.addEventListener('mouseleave', () => targetTooltip.style.display = 'none');

  // Hourly Charts
  function drawGenericHourlyChart(canvasId, tooltipId, key26, key25, color26, color25, formatter) {
    const cvs = document.getElementById(canvasId);
    const tip = document.getElementById(tooltipId);
    const hourlyData = currentDashboardData.hourly_chart || [];
    if (!cvs || !hourlyData.length) return;

    const isDark = root.classList.contains('dark');
    const gridColor = isDark ? '#1f2937' : '#e2e8f0';
    const textColor = isDark ? '#94a3b8' : '#64748b';

    const box = cvs.parentElement;
    const ratio = window.devicePixelRatio || 1;
    const width = box.clientWidth;
    const height = 320;
    cvs.width = width * ratio;
    cvs.height = height * ratio;
    cvs.style.height = height + 'px';

    const ctx = cvs.getContext('2d');
    ctx.scale(ratio, ratio);

    const maxVal = Math.max(...hourlyData.flatMap(x => [x[key26], x[key25]]), 1);
    const left = 56, bottom = 36, top = 20, right = 16;
    const plotW = width - left - right;
    const plotH = height - top - bottom;

    ctx.font = '11px sans-serif';
    ctx.fillStyle = textColor;
    ctx.strokeStyle = gridColor;
    ctx.lineWidth = 1;

    [0, 0.33, 0.66, 1].forEach(t => {
      const y = top + plotH * (1 - t);
      ctx.beginPath();
      ctx.moveTo(left, y);
      ctx.lineTo(width - right, y);
      ctx.stroke();
      ctx.textAlign = 'left';
      ctx.fillText(key26.includes('sales') ? 'Rp ' + Math.round(maxVal * t / 1000000) + 'jt' : Math.round(maxVal * t).toLocaleString('id-ID'), 6, y + 4);
    });

    const step = plotW / Math.max(hourlyData.length - 1, 1);
    const points = [];

    // Series 2025
    ctx.strokeStyle = color25;
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    hourlyData.forEach((item, i) => {
      const x = left + i * step;
      const y = top + plotH - (item[key25] / maxVal) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Series 2026
    ctx.strokeStyle = color26;
    ctx.lineWidth = 3;
    ctx.beginPath();
    hourlyData.forEach((item, i) => {
      const x = left + i * step;
      const y = top + plotH - (item[key26] / maxVal) * plotH;
      if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      points.push({ x, y, item });
    });
    ctx.stroke();

    // Markers
    hourlyData.forEach((item, i) => {
      const x = left + i * step;
      const y = top + plotH - (item[key26] / maxVal) * plotH;
      ctx.fillStyle = color26;
      ctx.beginPath();
      ctx.arc(x, y, 3.5, 0, Math.PI * 2);
      ctx.fill();
    });

    // Labels
    ctx.fillStyle = textColor;
    ctx.textAlign = 'center';
    ctx.font = '10px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
    const showEvery = step < 26 ? 2 : 1;
    hourlyData.forEach((item, i) => {
      const hrStr = String(parseInt(item.hour, 10)).padStart(2, '0');
      if (i % showEvery === 0 || i === hourlyData.length - 1) {
        ctx.fillText(hrStr, left + i * step, height - 10);
      }
    });

    cvs.onmousemove = function(e) {
      const rect = cvs.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      let nearest = points.reduce((a, p) => Math.hypot(p.x - x, p.y - y) < Math.hypot(a.x - x, a.y - y) ? p : a);
      if (Math.hypot(nearest.x - x, nearest.y - y) < 30) {
        const it = nearest.item;
        tip.style.display = 'block';
        tip.style.left = Math.min(nearest.x + 12, cvs.clientWidth - 200) + 'px';
        tip.style.top = Math.max(nearest.y - 90, 10) + 'px';
        tip.innerHTML = `
          <div class="tooltip-title">Pukul ${it.hour}:00</div>
          <div class="tooltip-row"><span class="tooltip-label">Tahun 2026:</span> <span class="tooltip-val">${formatter(it[key26])}</span></div>
          <div class="tooltip-row"><span class="tooltip-label">Tahun 2025:</span> <span class="tooltip-val">${formatter(it[key25])}</span></div>
        `;
      } else {
        tip.style.display = 'none';
      }
    };
    cvs.onmouseleave = () => tip.style.display = 'none';
  }

  function drawHourlySalesChart() {
    drawGenericHourlyChart('hourlySalesChart', 'hourlySalesTooltip', 'net_sales_2026', 'net_sales_2025', '#2563eb', '#a78bfa', formatRp);
  }

  function drawHourlyTxChart() {
    drawGenericHourlyChart('hourlyTransactionsChart', 'hourlyTransactionsTooltip', 'transactions_2026', 'transactions_2025', '#059669', '#cbd5e1', val => (val || 0).toLocaleString('id-ID') + ' Struk');
  }

  // Initial load & draw
  applyFilters();
  redrawAllCharts();
  updateActiveFilterTags();

  window.addEventListener('resize', redrawAllCharts);

  // Scroll to Top Smooth Handler
  const btnScrollTop = document.getElementById('btnScrollTop');
  window.addEventListener('scroll', () => {
    if (window.scrollY > 250) {
      btnScrollTop.classList.add('visible');
    } else {
      btnScrollTop.classList.remove('visible');
    }
  }, { passive: true });

  function scrollToTop() {
    window.scrollTo({
      top: 0,
      behavior: 'smooth'
    });
  }
